/**
 * Regional synergy unlock — first visit per region unlocks that region's synergies.
 */
import { RELEASED_REGION_IDS } from '../../constants/balance/regionRelease.ts';
import { SYNERGY_REGION_ORDER } from '../../constants/balance/teamSynergies/types.ts';
import { maxReachedZoneByRegion } from '../../gameManager.ts';
import type { GameRuntime } from '../types/game.js';

const KANTO_REGION = 'kanto';

export function defaultUnlockedSynergyRegionIds(): string[] {
    return [KANTO_REGION];
}

export function normalizeUnlockedSynergyRegionIds(raw: unknown): string[] {
    const out = new Set<string>([KANTO_REGION]);
    if (!Array.isArray(raw)) return [...out];
    for (let i = 0; i < raw.length; i++) {
        const id = String(raw[i] || '');
        if (id && (SYNERGY_REGION_ORDER as readonly string[]).includes(id)) {
            out.add(id);
        }
    }
    return SYNERGY_REGION_ORDER.filter((id) => out.has(id));
}

export function getUnlockedSynergyRegionIds(game: GameRuntime | null | undefined): string[] {
    if (!game) return defaultUnlockedSynergyRegionIds();
    const stored = (game as GameRuntime & { unlockedSynergyRegionIds?: string[] }).unlockedSynergyRegionIds;
    return normalizeUnlockedSynergyRegionIds(stored);
}

export function isSynergyRegionUnlocked(
    game: GameRuntime | null | undefined,
    regionId: string,
): boolean {
    const id = String(regionId || KANTO_REGION);
    if (id === KANTO_REGION) return true;
    return getUnlockedSynergyRegionIds(game).includes(id);
}

export function inferUnlockedSynergyRegionsFromProgress(
    byRegion?: Record<string, number> | null,
): string[] {
    const out = new Set<string>([KANTO_REGION]);
    const store = byRegion ?? maxReachedZoneByRegion;
    if (!store || typeof store !== 'object') return [...out];
    for (let i = 0; i < SYNERGY_REGION_ORDER.length; i++) {
        const regionId = SYNERGY_REGION_ORDER[i];
        if (!regionId || regionId === KANTO_REGION) continue;
        if (!(RELEASED_REGION_IDS as readonly string[]).includes(regionId)) continue;
        const maxZone = Number(store[regionId] || 0);
        if (Number.isFinite(maxZone) && maxZone > 0) out.add(regionId);
    }
    return SYNERGY_REGION_ORDER.filter((id) => out.has(id));
}

export function migrateUnlockedSynergyRegionIds(game: GameRuntime): void {
    const g = game as GameRuntime & { unlockedSynergyRegionIds?: string[] };
    const current = normalizeUnlockedSynergyRegionIds(g.unlockedSynergyRegionIds);
    const inferred = inferUnlockedSynergyRegionsFromProgress(
        game.maxReachedZoneByRegion as Record<string, number> | undefined,
    );
    const merged = new Set<string>([...current, ...inferred]);
    g.unlockedSynergyRegionIds = SYNERGY_REGION_ORDER.filter((id) => merged.has(id));
}

/**
 * Unlock synergies for a region on first visit. Returns true if newly unlocked.
 */
export function unlockSynergyRegion(
    game: GameRuntime | null | undefined,
    regionId: string,
): boolean {
    if (!game) return false;
    const id = String(regionId || '');
    if (!id || id === KANTO_REGION) return false;
    if (!(SYNERGY_REGION_ORDER as readonly string[]).includes(id)) return false;

    migrateUnlockedSynergyRegionIds(game);
    const g = game as GameRuntime & { unlockedSynergyRegionIds?: string[] };
    const list = getUnlockedSynergyRegionIds(game);
    if (list.includes(id)) return false;

    g.unlockedSynergyRegionIds = [...list, id];
    return true;
}

export function notifySynergyRegionUnlocked(game: GameRuntime, regionId: string): void {
    const regionLabels: Record<string, { fr: string; en: string }> = {
        johto: { fr: 'Johto', en: 'Johto' },
        hoenn: { fr: 'Hoenn', en: 'Hoenn' },
        sinnoh: { fr: 'Sinnoh', en: 'Sinnoh' },
        unova: { fr: 'Unova', en: 'Unova' },
        kalos: { fr: 'Kalos', en: 'Kalos' },
        alola: { fr: 'Alola', en: 'Alola' },
        galar: { fr: 'Galar', en: 'Galar' },
        paldea: { fr: 'Paldea', en: 'Paldea' },
    };
    const labels = regionLabels[regionId];
    if (!labels) return;

    const lang =
        typeof game.normalizeLanguage === 'function'
            ? game.normalizeLanguage(game.language)
            : game.language;
    const regionName = lang === 'fr' ? labels.fr : labels.en;
    const msgFr = `Nouvelles synergies ${regionName} disponibles !`;
    const msgEn = `New ${regionName} synergies available!`;
    const body = lang === 'fr' ? msgFr : msgEn;

    if (typeof game.logMessage === 'function') {
        game.logMessage(body);
    }
    const toast = (globalThis as { toast?: { success?: (t: string, b?: string) => void } }).toast;
    if (toast?.success) {
        toast.success(body, '');
    }
}

export function tryUnlockSynergyRegionOnVisit(
    game: GameRuntime | null | undefined,
    regionId: string,
): void {
    if (!game) return;
    const newly = unlockSynergyRegion(game, regionId);
    if (newly) notifySynergyRegionUnlocked(game, regionId);
}
