export interface RequiredSpeciesRule {
    species: string[];
    minCount: number;
}

export interface TeamSynergyDef {
    regionId: string;
    types?: string[];
    min_count?: number;
    all_required?: boolean;
    /** When true, only native species count toward type tallies. Default: all active team slots count. */
    regionalTypesOnly?: boolean;
    requiredSpecies?: RequiredSpeciesRule;
    effect: Record<string, number>;
    name: string;
    message: string;
}

export type TeamSynergyMap = Record<string, TeamSynergyDef>;

export const SYNERGY_REGION_ORDER = ['kanto', 'johto', 'hoenn', 'sinnoh', 'unova', 'kalos', 'alola', 'galar', 'paldea'] as const;

export type SynergyRegionId = (typeof SYNERGY_REGION_ORDER)[number];
