/**
 * Collection bonuses - passive bonuses based on complete family collections.
 * "Weakest Link" rule: bonus level = min(prestige) among all required members.
 * If one Pokemon is missing or has prestige 0 -> family bonus = 0.
 * Values in effect are per collection level: total += value * level.
 * Level = min(prestige) among members (>= 1), capped at COLLECTION_LEVEL_CAP (creatureVariants.ts).
 */
/** Final evolutions only (exceptions noted per family). Per-prestige bonus amounts. */
export type CollectionPokemonEntry = string | { name: string; shiny?: boolean };

export interface NormalizedCollectionMember {
    name: string;
    shinyRequired: boolean;
}

export type CollectionMemberStatus = 'missing' | 'needs_shiny' | 'prestige_0' | 'ok';

export interface ResolvedCollectionMember {
    name: string;
    shinyRequired: boolean;
    prestige: number;
    status: CollectionMemberStatus;
}

/** @param list string species name or `{ name, shiny?: true }` for chromatic requirement */
export function normalizeCollectionMembers(list: CollectionPokemonEntry[]): NormalizedCollectionMember[] {
    return list.map((entry) => {
        if (typeof entry === 'string') {
            return { name: entry, shinyRequired: false };
        }
        return { name: entry.name, shinyRequired: !!entry.shiny };
    });
}

function collectionMemberFamily(speciesName: string): string {
    const families = EVOLUTION_FAMILIES as Record<string, string>;
    const family = families[speciesName];
    return family ?? speciesName;
}

function evolutionTargets(def: EvolutionDefinition | undefined): string[] {
    if (!def) return [];
    if (def.evolves_to) return [def.evolves_to];
    if (def.options) {
        return def.options
            .map((opt) => opt.evolves_to)
            .filter((to): to is string => Boolean(to));
    }
    return [];
}

function buildEvolutionParentMap(
    evoMap: Record<string, EvolutionDefinition>,
): Map<string, string[]> {
    const parents = new Map<string, string[]>();
    for (const from of Object.keys(evoMap)) {
        for (const to of evolutionTargets(evoMap[from])) {
            const list = parents.get(to);
            if (list) list.push(from);
            else parents.set(to, [from]);
        }
    }
    return parents;
}

function isAncestorOf(
    ancestor: string,
    descendant: string,
    parents: Map<string, string[]>,
): boolean {
    const queue = [descendant];
    const seen = new Set<string>();
    while (queue.length > 0) {
        const cur = queue.shift();
        if (!cur || seen.has(cur)) continue;
        if (cur === ancestor) return true;
        seen.add(cur);
        const directParents = parents.get(cur);
        if (directParents) {
            for (let i = 0; i < directParents.length; i++) queue.push(directParents[i]);
        }
    }
    return false;
}

/** Roots where multiple end forms are siblings (Eevee, Ralts, Oddish, …) — no cross-species prestige. */
function buildCollectionBranchingFamilyRoots(): Set<string> {
    const families = EVOLUTION_FAMILIES as Record<string, string>;
    const evoMap = EVOLUTIONS as Record<string, EvolutionDefinition>;
    const parents = buildEvolutionParentMap(evoMap);

    const byRoot = new Map<string, Set<string>>();
    for (const name of Object.keys(families)) {
        const root = families[name];
        if (!root) continue;
        let set = byRoot.get(root);
        if (!set) {
            set = new Set<string>();
            byRoot.set(root, set);
        }
        set.add(name);
    }

    const branching = new Set<string>();
    for (const [root, membersSet] of byRoot) {
        if (membersSet.size <= 1) continue;

        const members = [...membersSet];
        const leaves = members.filter((m) => {
            const targets = evolutionTargets(evoMap[m]).filter((t) => membersSet.has(t));
            return targets.length === 0;
        });
        if (leaves.length < 2) continue;

        let hasSiblingLeaves = false;
        for (let i = 0; i < leaves.length && !hasSiblingLeaves; i++) {
            for (let j = i + 1; j < leaves.length; j++) {
                const a = leaves[i];
                const b = leaves[j];
                if (!isAncestorOf(a, b, parents) && !isAncestorOf(b, a, parents)) {
                    hasSiblingLeaves = true;
                    break;
                }
            }
        }
        if (hasSiblingLeaves) branching.add(root);
    }
    return branching;
}

export const COLLECTION_BRANCHING_FAMILY_ROOTS = buildCollectionBranchingFamilyRoots();

function collectionSpeciesMatchesMember(
    creatureName: string | null | undefined,
    member: NormalizedCollectionMember,
): boolean {
    if (!creatureName) return false;
    if (member.shinyRequired) return creatureName === member.name;
    const memberRoot = collectionMemberFamily(member.name);
    if (COLLECTION_BRANCHING_FAMILY_ROOTS.has(memberRoot)) {
        return creatureName === member.name;
    }
    return collectionMemberFamily(creatureName) === memberRoot;
}

export function resolveCollectionMembers(
    members: NormalizedCollectionMember[],
    creatures: Array<{ name?: string | null; prestige?: number; isShiny?: boolean }>,
): ResolvedCollectionMember[] {
    return members.map((member) => {
        let hasSpecies = false;
        let maxQualifiedPrestige = 0;
        for (let i = 0; i < creatures.length; i++) {
            const c = creatures[i];
            if (!c || !collectionSpeciesMatchesMember(c.name, member)) continue;
            hasSpecies = true;
            if (member.shinyRequired && !c.isShiny) continue;
            const p = c.prestige || 0;
            if (p > maxQualifiedPrestige) maxQualifiedPrestige = p;
        }
        let status: CollectionMemberStatus;
        if (!hasSpecies) {
            status = 'missing';
        } else if (member.shinyRequired && maxQualifiedPrestige === 0) {
            const hasShiny = creatures.some(
                (c) => c && c.name === member.name && !!c.isShiny,
            );
            status = hasShiny ? 'prestige_0' : 'needs_shiny';
        } else if (maxQualifiedPrestige === 0) {
            status = 'prestige_0';
        } else {
            status = 'ok';
        }
        return {
            name: member.name,
            shinyRequired: member.shinyRequired,
            prestige: Math.max(0, maxQualifiedPrestige),
            status,
        };
    });
}

