/**
 * Central team synergy evaluation — regional type counting, species rules, unlock gate.
 */
import { TEAM_SYNERGIES } from '../../constants/balance/teamSynergies.js';
import type { TeamSynergyDef } from '../../constants/balance/teamSynergies/types.ts';
import { getEggNativeRegionIdForSpecies } from '../../constants/balance/eggRegionMap.ts';
import { isSynergyRegionUnlocked } from './synergyRegionUnlock.ts';
import type { GameRuntime } from '../types/game.js';

export interface TeamSynergyMember {
    name?: string;
    type: string;
    secondaryType?: string | null;
}

export interface SynergyBonuses {
    attack_mult: number;
    spattack_mult: number;
    defense_mult: number;
    spdefense_mult: number;
    max_hp_mult: number;
    exp_mult: number;
    speed_mult: number;
    heal_mult: number;
    pokedollars_mult: number;
}

const MULT_FROM_ONE = new Set([
    'attack_mult',
    'spattack_mult',
    'defense_mult',
    'spdefense_mult',
    'max_hp_mult',
    'exp_mult',
    'speed_mult',
]);

export function emptySynergyBonuses(): SynergyBonuses {
    return {
        attack_mult: 1,
        spattack_mult: 1,
        defense_mult: 1,
        spdefense_mult: 1,
        max_hp_mult: 1,
        exp_mult: 1,
        speed_mult: 1,
        heal_mult: 0,
        pokedollars_mult: 0,
    };
}

function memberCountsForRegion(
    team: TeamSynergyMember[],
    regionId: string,
    regionalOnly: boolean,
): TeamSynergyMember[] {
    if (!regionalOnly) return team.filter(Boolean) as TeamSynergyMember[];
    return team.filter((c) => {
        if (!c?.name) return false;
        return getEggNativeRegionIdForSpecies(c.name) === regionId;
    });
}

export function countTeamTypesForSynergy(
    team: TeamSynergyMember[],
    syn: TeamSynergyDef,
): Record<string, number> {
    const regionalOnly = syn.regionalTypesOnly === true;
    const members = memberCountsForRegion(team, syn.regionId, regionalOnly);
    const typeCounts: Record<string, number> = {};
    for (let i = 0; i < members.length; i++) {
        const c = members[i];
        if (!c) continue;
        if (c.type) typeCounts[c.type] = (typeCounts[c.type] || 0) + 1;
        if (c.secondaryType) {
            typeCounts[c.secondaryType] = (typeCounts[c.secondaryType] || 0) + 1;
        }
    }
    return typeCounts;
}

function meetsSpeciesRequirement(team: TeamSynergyMember[], syn: TeamSynergyDef): boolean {
    const rule = syn.requiredSpecies;
    if (!rule || !Array.isArray(rule.species) || rule.species.length === 0) return true;
    const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
    const speciesList = rule.species;

    // AND mode (minCount covers full list): every listed species must be present once.
    if (minCount >= speciesList.length) {
        for (let i = 0; i < speciesList.length; i++) {
            const required = speciesList[i];
            let found = false;
            for (let j = 0; j < team.length; j++) {
                if (team[j]?.name === required) {
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }

    // OR / pick-N mode: count matching active slots toward minCount.
    const speciesSet = new Set(speciesList);
    let matched = 0;
    for (let i = 0; i < team.length; i++) {
        const c = team[i];
        if (!c?.name) continue;
        if (speciesSet.has(c.name)) matched++;
    }
    return matched >= minCount;
}

function meetsTypeRequirement(syn: TeamSynergyDef, typeCounts: Record<string, number>): boolean {
    const synTypes = syn.types;
    const minCount = syn.min_count;
    if (!Array.isArray(synTypes) || !synTypes.length || !minCount) {
        return true;
    }
    if (syn.all_required) {
        return synTypes.every((t) => (typeCounts[t] || 0) >= minCount);
    }
    return synTypes.some((t) => (typeCounts[t] || 0) >= minCount);
}

export function isSynergyActiveForTeam(
    syn: TeamSynergyDef,
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): boolean {
    if (!syn || !Array.isArray(team) || team.length === 0) return false;
    if (game && !isSynergyRegionUnlocked(game, syn.regionId)) return false;
    if (!meetsSpeciesRequirement(team, syn)) return false;
    const typeCounts = countTeamTypesForSynergy(team, syn);
    return meetsTypeRequirement(syn, typeCounts);
}

export function isSynergyActiveById(
    synergyId: string,
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): boolean {
    const syn = (TEAM_SYNERGIES as Record<string, TeamSynergyDef>)[synergyId];
    if (!syn) return false;
    return isSynergyActiveForTeam(syn, team, game);
}

export function getActiveSynergyEntries(
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): Array<{ id: string; def: TeamSynergyDef }> {
    if (!Array.isArray(team) || team.length === 0) return [];
    const synergies = TEAM_SYNERGIES as Record<string, TeamSynergyDef>;
    const out: Array<{ id: string; def: TeamSynergyDef }> = [];
    for (const id of Object.keys(synergies)) {
        const def = synergies[id];
        if (!def) continue;
        if (isSynergyActiveForTeam(def, team, game)) out.push({ id, def });
    }
    return out;
}

export function countActiveTeamSynergies(
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): number {
    return getActiveSynergyEntries(team, game).length;
}

export function hasActiveTeamSynergy(
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): boolean {
    return countActiveTeamSynergies(team, game) > 0;
}

export function aggregateSynergyEffects(
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): SynergyBonuses {
    const bonuses = emptySynergyBonuses();
    const active = getActiveSynergyEntries(team, game);
    const bonusRecord = bonuses as unknown as Record<string, number>;
    for (let i = 0; i < active.length; i++) {
        const entry = active[i];
        if (!entry) continue;
        const effect = entry.def.effect;
        if (!effect) continue;
        for (const [key, val] of Object.entries(effect)) {
            if (typeof val !== 'number' || val === 0) continue;
            if (MULT_FROM_ONE.has(key)) {
                bonusRecord[key] = (bonusRecord[key] ?? 1) + val;
            } else if (key === 'heal_mult' || key === 'pokedollars_mult') {
                bonusRecord[key] = (bonusRecord[key] ?? 0) + val;
            }
        }
    }
    return bonuses;
}

export function synergyBonusesToRecord(bonuses: SynergyBonuses): Record<string, number> {
    return { ...bonuses };
}
